insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-10',10,'listening','B1','Un horaire flexible','','Quelle obligation reste commune ?','["Arriver à huit heures","Travailler au bureau","Participer à la réunion de dix heures","Finir à seize heures"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-10',2,'La réunion impose une présence commune, éventuellement à distance.','listening-10.wav','Vous pouvez arriver entre huit heures et neuf heures trente. Mais tout le monde doit être présent à la réunion de dix heures, même en télétravail.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-11',11,'listening','B1','Un abonnement','','Quel conseil donne la personne ?','["Choisir une formule flexible en cas d’incertitude","Payer une année immédiatement","Annuler tout abonnement","Acheter deux formules"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-11',0,'L’abonnement mensuel laisse la possibilité d’arrêter.','listening-11.wav','La formule annuelle est moins chère au mois, mais elle engage pour douze mois. Si vous hésitez, prenez d’abord la formule mensuelle, sans engagement.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-12',12,'listening','B1','Une association','','De quoi l’association a-t-elle surtout besoin ?','["D’argent","De locaux","De vêtements","De bénévoles"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-12',3,'Le besoin concerne le temps de tri.','listening-12.wav','Nous ne manquons pas d’objets à distribuer, mais de personnes pour les trier. Deux heures le samedi nous aideraient davantage qu’un nouveau don de vêtements.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-13',13,'listening','B1','Une visite guidée','','Quelle conséquence ont les travaux ?','["La visite est annulée","La visite sera plus longue","Le billet sera plus cher","Le jardin sera fermé"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-13',1,'Le détour allonge la durée de quinze minutes.','listening-13.wav','Le parcours habituel est fermé pour travaux. Nous passerons par le jardin ; la visite durera quinze minutes de plus, sans supplément.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-14',14,'listening','B2','Un entretien radio','','Que remet en cause l’intervenante ?','["La valeur des bibliothèques","Le prix des livres","La pertinence d’un indicateur unique","La lecture sur téléphone"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-14',2,'Les achats ne couvrent pas toutes les pratiques de lecture.','listening-14.wav','On dit que les jeunes ne lisent plus. Pourtant, on mesure souvent seulement les livres achetés. Les lectures sur téléphone, les emprunts et les textes partagés échappent à ce chiffre.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-15',15,'listening','B2','Au travail','','Quel bilan est proposé ?','["Le gain local ne garantit pas un gain global","Le logiciel ne fonctionne jamais","La saisie est devenue plus lente","Les dossiers doivent être supprimés"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-15',0,'Le temps économisé peut être absorbé par d’autres tâches.','listening-15.wav','Le nouveau logiciel nous fait gagner du temps pour saisir les dossiers. Mais nous passons maintenant ce temps à corriger les classements automatiques. Il faudrait mesurer l’ensemble du processus.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-16',16,'listening','B2','Un quartier en débat','','Quelle est la position du commerçant ?','["Il refuse les vélos","Il demande un stationnement permanent","Il veut fermer la rue","Il souhaite aménager le projet"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-16',3,'Il soutient le principe sous réserve d’une organisation des livraisons.','listening-16.wav','Je suis favorable aux pistes cyclables. Ce que je demande, c’est de maintenir un accès pour les livraisons tôt le matin. On peut concilier les deux si l’on discute des horaires.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-17',17,'listening','B2','Une chercheuse','','Quelle prudence exprime-t-elle ?','["Les résultats sont inutiles","Une corrélation ne suffit pas à établir une causalité exclusive","Le sommeil ne compte jamais","Les conditions de vie sont identiques"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-17',1,'D’autres facteurs peuvent contribuer à l’association observée.','listening-17.wav','Nous avons observé une relation entre sommeil et réussite. Cela ne prouve pas, à lui seul, que dormir davantage explique tous les résultats : les conditions de vie interviennent aussi.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-18',18,'listening','B2','Une émission québécoise','','Quel enjeu est souligné ?','["Le remplacement des téléphones","Le prix du permis","La couverture territoriale du service","La suppression des réservations"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-18',2,'Une bonne application ne compense pas le manque de véhicules proches.','listening-18.wav','L’autopartage fonctionne bien au centre-ville. Mais dans les secteurs où les véhicules sont rares, réserver devient une petite expédition. Étendre le réseau compte autant que proposer une application pratique.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-19',19,'listening','B2','L’enseignement','','Pourquoi l’enseignant diffère-t-il la réponse ?','["Pour favoriser la réflexion","Pour gagner du temps","Pour sanctionner l’élève","Pour éviter le sujet"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-19',0,'L’explication du raisonnement est un outil d’apprentissage.','listening-19.wav','Donner la bonne réponse immédiatement rassure l’élève, mais peut lui retirer l’occasion de comprendre son erreur. Je préfère parfois lui demander d’expliquer son raisonnement.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-20',20,'listening','B2','Un restaurateur','','Quel compromis est présenté ?','["Des prix plus élevés contre un meilleur décor","Une cuisine plus rapide mais moins fraîche","Plus de choix avec plus de déchets","Moins de choix permanent avec davantage de fraîcheur"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-20',3,'La réduction de la carte permet de suivre les arrivages.','listening-20.wav','Notre carte est plus courte depuis un mois. Certains clients s’en étonnent, puis apprécient que les plats changent avec les arrivages. Nous gaspillons moins et cuisinons plus frais.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-21',21,'listening','B2','Une médiatrice','','Quel est l’objectif ?','["Obtenir une opinion unique","Maintenir un dialogue malgré le désaccord","Éviter tous les sujets sensibles","Désigner un gagnant"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-21',1,'La médiation vise les conditions du dialogue.','listening-21.wav','Nous ne cherchons pas à faire disparaître les divergences. Nous voulons que chacun puisse les exprimer sans que la discussion s’interrompe au premier désaccord.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-22',22,'listening','B2','La rénovation','','Quel risque est évoqué ?','["Une baisse de température","Une hausse de la consommation","L’éviction des bénéficiaires visés","Une disparition des bâtiments"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-22',2,'Le bénéfice écologique peut s’accompagner d’un déplacement social.','listening-22.wav','Isoler les bâtiments est indispensable. Encore faut-il vérifier que l’augmentation des loyers ne chasse pas les habitants auxquels les économies d’énergie étaient censées profiter.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-23',23,'listening','C1','Un débat culturel','','Que propose l’intervenante ?','["Élargir les critères d’évaluation du succès","Limiter le nombre de visiteurs","Supprimer les statistiques","Rendre le musée payant"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-23',0,'La fréquentation brute ne décrit pas toute l’accessibilité culturelle.','listening-23.wav','Je me réjouis que le musée attire davantage de visiteurs. Mais le succès ne se résume pas aux entrées : il faut savoir qui revient, qui se sent accueilli et qui n’ose toujours pas franchir la porte.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-24',24,'listening','C1','Une sociologue','','Quelle critique formule-t-elle ?','["Les habitants sont indécis","Il y a trop d’options","Toute consultation est inutile","Une consultation sans pouvoir de cadrage peut être purement formelle"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-24',3,'La participation suppose un pouvoir sur la définition du problème.','listening-24.wav','Quand on demande aux habitants de participer après avoir fixé toutes les options, on recueille surtout leur assentiment. La participation commence vraiment lorsqu’ils peuvent redéfinir la question.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-25',25,'listening','C1','La gestion du risque','','Quel usage de l’argument est critiqué ?','["L’étude probabiliste","Son emploi pour éviter de justifier les choix","La publication des données","Le refus de promettre l’impossible"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-25',1,'L’impossibilité du risque nul ne légitime pas n’importe quel arbitrage.','listening-25.wav','Le risque zéro n’existe pas. Le dire ne dispense toutefois pas d’expliquer quels risques sont acceptés, par qui, et au bénéfice de qui. Sinon, une évidence technique devient une dispense de responsabilité.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-26',26,'listening','C1','Une chronique','','Quelle tension apparaît ?','["La liberté totale nuit aux résultats","Les objectifs sont absents","L’autonomie proclamée n’inclut pas la maîtrise des décisions","Les salariés refusent toute responsabilité"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-26',2,'La responsabilité est transférée sans pouvoir correspondant.','listening-26.wav','On félicite les salariés autonomes, à condition qu’ils atteignent des objectifs dont ils ne discutent ni la pertinence ni les moyens. Cette autonomie-là ressemble parfois à une responsabilité sans pouvoir.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-27',27,'listening','C1','L’économie circulaire','','Que suggère l’orateur ?','["Agir sur les incitations économiques","Cesser de réparer","Blâmer les consommateurs","Interdire tous les appareils"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-27',0,'Les conditions économiques doivent rendre la réparation praticable.','listening-27.wav','Réparer un appareil est une bonne chose. Mais si la réparation reste plus chère que le remplacement, invoquer la seule bonne volonté du consommateur laisse intact le système qui décourage le geste attendu.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-28',28,'listening','C1','L’histoire locale','','Quelle idée est contestée ?','["La nécessité du débat","L’existence du monument","La pluralité des lectures","L’existence d’un sens mémoriel unique et stable"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-28',3,'Le sens du monument s’est transformé historiquement.','listening-28.wav','Le monument paraît immuable. Pourtant, le sens qu’on lui attribue a changé plusieurs fois. Le débat actuel ne détruit donc pas une mémoire intacte ; il poursuit une histoire d’interprétations.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-29',29,'listening','C1','La traduction','','Quel paradoxe est exposé ?','["La traduction doit être littérale","Une transformation formelle peut préserver l’intention","Toute traduction est impossible","La courtoisie est universelle"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-29',1,'La fonction pragmatique peut exiger une formulation différente.','listening-29.wav','Traduire mot à mot peut préserver les unités et perdre le geste. Une formule courtoise dans une langue peut sembler distante dans une autre. La fidélité exige parfois de s’écarter de la forme.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-30',30,'listening','C1','Une décision publique','','Quelle exigence est posée ?','["Ne jamais agir dans l’urgence","Maintenir toutes les mesures","Réexaminer les décisions exceptionnelles","Supprimer toute règle"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-30',2,'Une justification temporaire impose une réévaluation ultérieure.','listening-30.wav','L’urgence justifie de décider vite. Elle ne justifie pas que les mesures provisoires se prolongent sans examen. Ce qui était défendable faute de temps doit pouvoir être rediscuté lorsque ce temps revient.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-31',31,'listening','C1','Un philosophe','','Quelle position défend-il ?','["Confronter les principes aux effets de leur application","Abandonner tous les principes","Ne juger que les intentions","Éviter toute action"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-31',0,'La portée normative des principes se vérifie aussi dans leurs effets.','listening-31.wav','À force d’opposer les principes aux conséquences, on oublie que nos principes ont précisément pour vocation d’orienter une action dans le monde. Les soustraire à toute confrontation avec leurs effets, c’est parfois les vider de leur exigence.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-32',32,'listening','C1','Une éditrice','','Quelle distinction est essentielle ?','["Longueur et brièveté","Fiction et essai","Original et traduction","Complexité du sujet et obscurité de l’expression"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-32',3,'L’obscurité stylistique ne prouve pas la profondeur.','listening-32.wav','Un texte difficile n’est pas nécessairement profond, pas plus qu’un texte clair n’est simpliste. La question est de savoir si la difficulté est celle de l’objet ou celle que l’écriture lui ajoute inutilement.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-33',33,'listening','C2','La reconnaissance','','Quelle limite est dénoncée ?','["Le manque de compliments","Une reconnaissance subordonnée à une identité figée","L’excès de transformations","La disparition des différences"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-33',1,'L’accueil conditionnel peut enfermer une personne dans une représentation.','listening-33.wav','Être reconnu à condition de correspondre à l’image que l’autre se fait de vous, est-ce encore être reconnu ? La reconnaissance devient fragile lorsqu’elle ne laisse aucune place à la transformation de celui qu’elle prétend accueillir.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-34',34,'listening','C2','Le débat scientifique','','Quelle distinction est demandée ?','["Science publique et science privée","Chercheurs anciens et débutants","Validité des connaissances et légitimité de leurs applications","Majorité et unanimité"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-34',2,'Une critique des usages ne contredit pas nécessairement les résultats.','listening-34.wav','Une controverse n’est pas résolue en additionnant les voix. Mais l’expertise ne gagne rien à traiter toute objection comme une ignorance. Il lui faut distinguer ce qui conteste les résultats de ce qui interroge les usages qu’on en fait.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-35',35,'listening','C2','La mémoire collective','','Quel effet possible est décrit ?','["Une mémoire institutionnalisée peut marginaliser d’autres souvenirs","Toute commémoration efface tout souvenir","La mémoire est impossible","Le récit commun reste toujours ouvert"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-35',0,'La sélection officielle peut réduire la pluralité des mémoires.','listening-35.wav','L’oubli n’est pas toujours le contraire de la mémoire. Une commémoration très codifiée peut fixer ce qu’il faut retenir et rendre moins audibles les souvenirs qui résistent à ce récit commun.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-36',36,'listening','C2','Une économiste','','Que risque de masquer cet éloge ?','["La fréquence des adaptations","Le courage individuel","L’existence des crises","Les causes structurelles des crises"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-36',3,'L’attention portée à l’adaptation peut détourner de la prévention structurelle.','listening-36.wav','On présente la résilience comme la capacité de s’adapter aux crises. Mais si l’on célèbre uniquement l’adaptation de ceux qui les subissent, on risque de ne plus interroger les décisions qui les rendent récurrentes.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-37',37,'listening','C2','L’ironie d’un chroniqueur','','Quelle intention domine ?','["Féliciter la modernisation","Dénoncer ironiquement une complication","Expliquer une procédure neutre","Demander une nouvelle application"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-37',1,'Le compliment initial est contredit par l’accumulation des obstacles.','listening-37.wav','Quelle merveilleuse simplification : il faut désormais trois applications, deux comptes et un code reçu par courrier pour demander le document que le guichet délivrait en cinq minutes.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-38',38,'listening','C2','La transmission','','Quelle conception est défendue ?','["La reproduction fidèle de chaque usage","Le rejet de tout héritage","Une appropriation qui transforme l’héritage","La conservation sans interprétation"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-38',2,'La transmission vivante implique une réinterprétation.','listening-38.wav','Transmettre n’est pas remettre un objet intact à quelqu’un qui le garderait intact à son tour. C’est accepter qu’il change de sens dans des mains nouvelles, sans quoi on ne transmettrait qu’une obligation de répétition.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-listening','listening-39',39,'listening','C2','Le langage de la nécessité','','Quelle inférence est récusée ?','["D’un problème incontournable découlerait une solution unique","Un problème peut être discuté","Une réforme peut avoir des raisons","Plusieurs solutions peuvent exister"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-listening','listening-39',0,'L’existence d’une contrainte ne détermine pas à elle seule une réponse.','listening-39.wav','Dire qu’une réforme est nécessaire peut ouvrir une discussion sur ses raisons. Dire qu’elle est la seule possible tend au contraire à soustraire ses modalités au débat. La nécessité du problème ne rend pas unique sa solution.') on conflict(test_id,question_id) do nothing;
insert into public.tests(id,skill,mode,title,duration_seconds,question_count,published) values('official-reading','reading','official','TCFme official reading',3600,39,true) on conflict(id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-1',1,'reading','A1','À la bibliothèque','La bibliothèque ferme à 18 h du lundi au vendredi. Le samedi, elle ouvre de 9 h à 13 h.','Quand peut-on venir le samedi ?','["À 10 h","À 15 h","À 18 h","À 20 h"]',null,null,null,null) on conflict(test_id,id) do nothing;
