insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-2',2,'reading','A1','Un rendez-vous','Bonjour Léa, notre rendez-vous de mardi est déplacé à jeudi, à la même heure : 14 h. À bientôt !','Quand a lieu le rendez-vous ?','["Mardi à 14 h","Jeudi à 14 h","Jeudi à 16 h","Mardi à 16 h"]',null,null,null,null) on conflict(test_id,id) do nothing;
