insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-3',3,'reading','A1','Petite annonce','À louer : studio meublé, proche du métro. Loyer : 720 euros, eau comprise. Électricité en supplément.','Quelle dépense est incluse ?','["L’électricité","Internet","L’eau","Le transport"]',null,null,null,null) on conflict(test_id,id) do nothing;
