insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-4',4,'reading','A1','Au musée','Les visiteurs de moins de 18 ans entrent gratuitement. Pour les autres, le billet coûte 8 euros.','Qui ne paie pas ?','["Tous les visiteurs","Les plus de 65 ans","Les étudiants de 25 ans","Les enfants de 12 ans"]',null,null,null,null) on conflict(test_id,id) do nothing;
