insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-5',5,'reading','A2','Une livraison','Votre colis sera livré vendredi entre 8 h et 12 h. En cas d’absence, il sera déposé au point relais situé face à la mairie.','Où retirer le colis si vous êtes absent ?','["À la mairie","Dans un point relais","Chez un voisin","À la poste centrale"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-5',1,'Le dépôt annoncé est au point relais, en face de la mairie.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-6',6,'reading','A2','Un atelier','L’atelier de réparation est ouvert à tous. Apportez votre objet et ses pièces de rechange. Les bénévoles vous aident, mais ne réparent pas à votre place.','Que doit faire le participant ?','["Acheter un objet neuf","Déposer son objet et partir","Participer à la réparation","Payer les bénévoles"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-6',2,'L’aide accompagne une réparation faite par le participant.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-7',7,'reading','A2','La piscine','À partir de lundi, le bassin sera réservé aux écoles chaque matin. Les particuliers pourront nager à partir de midi, sauf le mercredi où l’ouverture reste fixée à 9 h.','Quand un particulier peut-il nager mercredi ?','["Dès 9 h","Seulement après midi","Uniquement le soir","À aucun moment"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-7',0,'Le mercredi constitue une exception explicite.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-8',8,'reading','A2','Une inscription','Les dossiers reçus avant le 15 mai seront examinés en priorité. Les dossiers tardifs pourront être étudiés si des places restent disponibles.','Que signifie un envoi après le 15 mai ?','["L’admission est garantie","Le tarif double","Le dossier est détruit","L’examen du dossier reste possible"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-8',3,'Un dépôt tardif est conditionné aux places restantes.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-9',9,'reading','B1','Un voyage partagé','Le covoiturage du village fonctionne sur réservation. Une place réservée mais non annulée la veille sera facturée, même en cas d’absence.','Dans quel cas paie-t-on sans voyager ?','["Si le conducteur annule","Si l’on oublie d’annuler à temps","Si l’on réserve la veille","Si le trajet est complet"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-9',1,'L’absence sans annulation dans les délais entraîne une facturation.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-10',10,'reading','B1','Travailler autrement','L’entreprise propose deux jours de télétravail, sous réserve que chaque équipe maintienne une présence quotidienne au bureau. Les salariés doivent donc coordonner leurs choix.','Quelle condition limite la liberté de choix ?','["L’ancienneté des salariés","La distance du domicile","La présence quotidienne d’une partie de l’équipe","L’achat d’un ordinateur"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-10',2,'L’organisation collective prime sur le choix individuel des jours.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-11',11,'reading','B1','Une place publique','Après trois mois d’essai, la mairie maintient la piétonnisation du dimanche. Les commerçants observent moins de passages rapides, mais davantage de clients qui restent dans le quartier.','Quel bilan les commerçants font-ils ?','["Tous leurs clients ont disparu","Les habitudes de fréquentation ont changé","Les ventes ont nécessairement doublé","La rue reste ouverte aux voitures"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-11',1,'Le texte oppose rapidité du passage et durée de présence, sans chiffrer les ventes.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-12',12,'reading','B1','Une formation','Le cours est gratuit pour les demandeurs d’emploi. Toutefois, une caution est demandée puis remboursée à ceux qui assistent à au moins huit séances sur dix.','À quoi sert la caution ?','["À encourager l’assiduité","À financer les diplômes","À sélectionner les meilleurs","À payer chaque séance"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-12',0,'Le remboursement dépend de la présence, non des résultats.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-13',13,'reading','B1','Une collecte','La collecte locale accepte les vêtements propres, même démodés. En revanche, les articles humides sont refusés : ils risquent d’abîmer tout le lot.','Pourquoi certains articles sont-ils refusés ?','["Parce qu’ils sont anciens","Parce qu’ils sont bon marché","Pour protéger les autres vêtements","Parce qu’ils sont trop nombreux"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-13',2,'L’humidité peut détériorer l’ensemble de la collecte.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-14',14,'reading','B2','Le temps des réunions','Supprimer une réunion ne supprime pas nécessairement le travail qu’elle organisait. Faute de règles claires, les échanges se dispersent dans des messages plus nombreux, et le gain de temps annoncé s’évanouit.','Quelle idée l’auteur défend-il ?','["Toute réunion est indispensable","Les messages doivent être interdits","Les réunions augmentent toujours la productivité","Réduire les réunions exige de repenser la coordination"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-14',3,'La critique porte sur l’absence de solution organisationnelle.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-15',15,'reading','B2','Manger local','La proximité géographique est un indicateur utile, mais incomplet. Un produit cultivé sous serre chauffée à quelques kilomètres peut consommer plus d’énergie qu’un produit de saison transporté de plus loin.','Quelle conclusion peut-on tirer ?','["Local signifie toujours écologique","Il faut considérer le mode de production","Le transport est sans effet","Les serres sont toutes interdites"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-15',1,'Le bilan dépend aussi des conditions de production.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-16',16,'reading','B2','Les transports gratuits','La gratuité attire des usagers, mais une ligne rare et saturée reste peu séduisante pour ceux qui disposent d’une voiture. Le prix n’est qu’un élément du choix de mobilité.','Quelle mesure complémentaire est suggérée ?','["Améliorer la fréquence et la capacité","Augmenter le stationnement","Interdire les vélos","Supprimer les lignes rurales"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-16',0,'Le texte souligne deux obstacles de qualité de service.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-17',17,'reading','B2','Lire les statistiques','Le salaire moyen a progressé, alors que la moitié des employés n’a reçu aucune augmentation. Quelques fortes hausses au sommet suffisent à modifier la moyenne sans améliorer la situation de la majorité.','Que révèle cet exemple ?','["La moyenne est nécessairement fausse","Tous les salaires ont diminué","Un indicateur global peut masquer des écarts","Les hausses individuelles sont impossibles"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-17',2,'La moyenne agrège les valeurs sans décrire leur répartition.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-18',18,'reading','B2','Une ville fraîche','Planter des arbres est nécessaire, mais les compter ne suffit pas. Une jeune plantation n’offre ni l’ombre ni la résistance d’un arbre ancien. Préserver l’existant doit donc accompagner les annonces de nouvelles plantations.','Que critique l’auteur ?','["L’usage des espaces publics","L’attention exclusive au nombre d’arbres plantés","Toute plantation nouvelle","Le coût des jardins privés"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-18',1,'Le nombre ne rend pas compte du service écologique effectif.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-19',19,'reading','B2','L’apprentissage numérique','La plateforme promet un parcours personnalisé. Pourtant, ses recommandations se fondent surtout sur les réponses passées. Un élève momentanément en difficulté peut alors recevoir des exercices toujours plus faciles et ne plus rencontrer de nouveaux défis.','Quel risque est décrit ?','["L’absence de données","Un apprentissage trop rapide","Une suppression des exercices","L’enfermement dans un profil initial"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-19',3,'Les recommandations peuvent figer la difficulté au lieu de soutenir la progression.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-20',20,'reading','B2','La semaine courte','Passer à quatre jours sans réduire la charge peut accroître l’intensité du travail. Le bénéfice dépend donc moins du calendrier que de la capacité à supprimer les tâches inutiles et à fixer des priorités.','Quelle distinction organise l’argument ?','["Durée affichée et organisation réelle","Salaire public et salaire privé","Travail manuel et travail intellectuel","Repos individuel et repos collectif"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-20',0,'Un calendrier réduit ne garantit pas une charge réduite.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-21',21,'reading','B2','Le patrimoine vivant','Restaurer un marché en conservant ses façades, mais en remplaçant ses commerces par des boutiques de luxe, sauve une image et transforme un usage. La préservation matérielle peut ainsi coïncider avec une rupture sociale.','Quel paradoxe est mis en évidence ?','["La restauration détruit toutes les façades","Les commerces ne changent jamais","On peut préserver le bâti tout en perdant une fonction collective","Le luxe protège nécessairement les habitants"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-21',2,'L’opposition porte sur le patrimoine architectural et la vie sociale.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-22',22,'reading','B2','L’information en continu','La rapidité devient un avantage commercial lorsqu’elle précède la vérification. Mais ce qui attire l’attention à court terme peut détériorer durablement la confiance dont dépend le média.','Quel conflit l’auteur identifie-t-il ?','["Neutralité et absence de lecteurs","Rentabilité immédiate et crédibilité durable","Presse écrite et radio","Vitesse de lecture et taille des écrans"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-22',1,'L’intérêt commercial immédiat peut miner la confiance future.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-23',23,'reading','C1','La mesure du mérite','Un concours identique pour tous ne neutralise pas les inégalités de préparation. Confondre l’uniformité de la procédure avec l’équité des conditions revient à attribuer aux seuls individus des écarts dont une partie les précède.','Quelle présupposition est contestée ?','["La nécessité de critères","L’existence d’efforts personnels","La possibilité d’un concours","L’égalité des règles suffirait à assurer l’équité"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-23',3,'Des règles identiques ne compensent pas des conditions initiales inégales.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-24',24,'reading','C1','L’expertise en débat','Reconnaître les limites d’un modèle n’invalide pas l’expertise ; c’est au contraire rendre explicite le domaine où elle éclaire la décision. L’assurance sans réserve, elle, confond autorité scientifique et posture d’infaillibilité.','Quelle conception de l’expertise est privilégiée ?','["Une compétence qui explicite son incertitude","Une certitude définitive","Une opinion équivalente à toute autre","Une autorité soustraite au débat"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-24',0,'L’incertitude circonscrite contribue à la rigueur de l’expertise.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-25',25,'reading','C1','La sobriété choisie','L’injonction à consommer moins paraît consensuelle tant qu’elle reste abstraite. Elle change de sens selon qu’elle vise un confort superflu ou un besoin déjà contraint. Sans cette distinction, la sobriété risque de devenir le langage vertueux d’une privation imposée.','Quel préalable l’auteur exige-t-il ?','["Supprimer toute consommation","Reconnaître l’inégale marge de choix","Appliquer un quota identique","Renoncer aux objectifs écologiques"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-25',1,'Le texte distingue renoncement volontaire et privation subie.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-26',26,'reading','C1','Des données ouvertes','Ouvrir une base ne la rend pas intelligible. Sans documentation des catégories, des absences et des changements de méthode, la transparence formelle peut nourrir des conclusions plus trompeuses que le silence.','Quelle condition rend l’ouverture utile ?','["La multiplication des chiffres","L’anonymat des producteurs","L’explication des choix de construction","La suppression des données manquantes"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-26',2,'Les métadonnées permettent d’interpréter correctement les chiffres.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-27',27,'reading','C1','L’hospitalité urbaine','Une place peut être accessible en droit et dissuasive dans ses aménagements. Les assises empêchant de s’allonger matérialisent une sélection des usages sans qu’aucune interdiction n’ait à être formulée.','Que révèle l’aménagement décrit ?','["Une augmentation du confort","Une absence de choix politique","Une simple contrainte esthétique","Une exclusion opérée par la conception matérielle"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-27',3,'Le mobilier impose implicitement une règle d’usage.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-28',28,'reading','C1','Le droit à l’erreur','Une institution qui célèbre l’expérimentation tout en sanctionnant chaque échec produit moins de prudence que de dissimulation. On ne peut demander aux agents de prendre des risques et leur retirer simultanément la possibilité d’en rendre compte.','Quel mécanisme est dénoncé ?','["Une injonction contradictoire favorisant la dissimulation","Un excès de transparence","Une absence totale de sanctions","La généralisation de l’imprudence"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-28',0,'L’écart entre discours et sanctions encourage à cacher les échecs.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-29',29,'reading','C1','L’attention comme ressource','L’abondance des contenus ne se traduit pas mécaniquement par un élargissement des horizons. Lorsque leur sélection récompense surtout ce qui retient déjà notre attention, la diversité disponible peut croître tandis que la diversité effectivement rencontrée se rétrécit.','Quelle distinction fonde le raisonnement ?','["Création et propriété","Offre potentielle et exposition réelle","Information et divertissement","Gratuité et abonnement"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-29',1,'La diversité du catalogue ne garantit pas celle des contenus proposés.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-30',30,'reading','C1','Un futur négociable','Présenter une technologie comme inéluctable dispense de discuter les institutions qui la façonnent. Ce récit ne décrit pas seulement un avenir : il réduit le champ des futurs qu’il devient légitime d’envisager.','Quelle fonction le récit remplit-il ?','["Il prouve une nécessité technique","Il ouvre toutes les options","Il restreint politiquement les alternatives","Il décrit uniquement le passé"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-30',2,'L’inéluctabilité proclamée ferme le débat sur les choix collectifs.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-31',31,'reading','C1','Une neutralité située','Le protocole ne contient aucun critère explicitement discriminatoire. Encore faut-il examiner les variables qu’il prend pour acquises : un indicateur apparemment neutre peut hériter des inégalités du monde dont il est extrait.','Que signifie « hériter » ici ?','["Corriger automatiquement","Être transmis juridiquement","Mesurer sans sélection","Reproduire indirectement des inégalités antérieures"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-31',3,'La neutralité formelle peut conserver des biais présents dans les données.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-32',32,'reading','C1','Le compromis','Le compromis n’est fécond ni parce qu’il partagerait chaque désaccord en deux, ni parce qu’il ferait disparaître le conflit. Il l’est lorsqu’il transforme les conditions dans lesquelles les parties peuvent continuer à agir ensemble sans feindre de penser de même.','Quelle définition est proposée ?','["Un accord pratique compatible avec un désaccord persistant","Une moyenne arithmétique des opinions","Une conversion réciproque complète","Une suspension de toute action"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-32',0,'La coopération n’exige pas l’identité des convictions.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-33',33,'reading','C2','L’archive et l’oubli','Ce que conserve une archive témoigne aussi des procédures qui ont décidé de sa conservation. Prendre son silence pour la preuve d’une absence revient à effacer une seconde fois ceux dont la parole n’avait pas vocation à y entrer.','Quelle erreur méthodologique est visée ?','["Dater les documents","Confondre absence de trace et inexistence historique","Comparer plusieurs archives","Décrire les procédures de collecte"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-33',1,'Le corpus reflète une sélection préalable, non la totalité du passé.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-34',34,'reading','C2','L’éloge du provisoire','On reproche au provisoire de ne pas tenir ses promesses de permanence. Mais c’est lui prêter un projet qui n’est pas le sien. Une décision révisable peut être plus responsable qu’un engagement dont la solennité interdit ensuite de reconnaître les effets indésirables.','Quel renversement l’auteur opère-t-il ?','["L’irréversibilité devient un idéal","Toute promesse devient inutile","La révisabilité devient une exigence de responsabilité","L’inaction devient une décision"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-34',2,'La capacité de corriger est valorisée comme une responsabilité.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-35',35,'reading','C2','La communauté imaginée','On invoque volontiers une communauté pour légitimer une décision prise en son nom. Reste à savoir si ce « nous » désigne ceux qui ont participé à la délibération ou ceux à qui l’on demande seulement d’en assumer les conséquences.','Quelle ambiguïté est examinée ?','["Le sens géographique de communauté","L’opposition entre passé et avenir","Le nombre exact des participants","L’écart entre auteurs et destinataires d’une décision collective"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-35',3,'Le pronom collectif peut masquer une dissymétrie de pouvoir.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-36',36,'reading','C2','La lenteur administrative','Que la lenteur protège parfois de l’arbitraire ne suffit pas à en faire une vertu en soi. Tout dépend de ce qu’elle suspend : la précipitation d’un pouvoir ou l’exercice d’un droit. Un même délai peut être garantie pour l’un et déni pour l’autre.','À quoi tient l’ambivalence du délai ?','["À l’objet suspendu et à la position des personnes","À sa seule durée","À l’intention toujours malveillante des agents","À l’inutilité des procédures"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-36',0,'Le jugement dépend de la fonction du délai et de ses effets différenciés.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-37',37,'reading','C2','Le récit de la réussite','Le récit rétrospectif donne aux bifurcations heureuses l’allure d’une trajectoire maîtrisée. Ce n’est pas qu’il invente tous les faits ; il redistribue leur nécessité, reléguant la contingence au rang de décor.','Quelle opération narrative est décrite ?','["La fabrication intégrale des événements","La transformation du hasard en cohérence apparente","Le refus de toute causalité","La disparition des protagonistes"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-37',1,'Le récit construit après coup une nécessité qui n’existait pas dans l’action.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-38',38,'reading','C2','La promesse d’inclusion','Inclure peut signifier inviter chacun à rejoindre un cadre inchangé, ou reconnaître à ceux qui arrivent le pouvoir d’en modifier les règles. Entre ces deux gestes se joue moins une différence de générosité qu’une redistribution de l’autorité.','Quel critère distingue les deux conceptions ?','["Le nombre de bénéficiaires","Le coût de l’accueil","La capacité des nouveaux venus à transformer le cadre","La rapidité des invitations"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-38',2,'La seconde conception partage le pouvoir de définir les règles.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-reading','reading-39',39,'reading','C2','L’exigence de preuve','Il est légitime d’exiger des preuves d’un dommage ; il l’est moins de fixer un seuil que seule la survenue irréversible du dommage permettrait d’atteindre. La rigueur apparente peut alors devenir une manière de rendre la prévention conceptuellement impossible.','Quel paradoxe est dénoncé ?','["La prévention dispense de toute preuve","Le dommage est toujours mesurable","La preuve interdit toute décision","Un standard probatoire peut n’être satisfait qu’une fois la prévention devenue impossible"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('official-reading','reading-39',3,'Le seuil exigé peut contredire la finalité préventive de la décision.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.tests(id,skill,mode,title,duration_seconds,question_count,published) values('official-writing','writing','official','TCFme official writing',3600,3,true) on conflict(id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-writing','writing-1',1,'writing','B1','Un nouveau quartier','Vous venez d’emménager dans un nouveau quartier à Montréal.','Écrivez un message à une amie pour décrire votre quartier, expliquer ce qui vous plaît et l’inviter à vous rendre visite. Donnez les renseignements pratiques nécessaires.','[]',60,120,null,null) on conflict(test_id,id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-writing','writing-2',2,'writing','C1','Une expérience qui fait réfléchir','Vous avez participé à un atelier de réparation d’objets dans votre ville.','Rédigez un article pour le site de votre association. Racontez votre expérience, expliquez ce que vous en avez retiré et donnez votre avis sur l’intérêt de ces initiatives.','[]',120,150,null,null) on conflict(test_id,id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-writing','writing-3',3,'writing','C2','La ville sans voiture : progrès ou exclusion ?','Document 1 · Réduire la place de la voiture rend l’air plus sain et libère des espaces de rencontre. Une ville accueillante se mesure à la place qu’elle laisse aux piétons.
insert into public.tests(id,skill,mode,title,duration_seconds,question_count,published) values('official-speaking','speaking','official','TCFme official speaking',720,3,true) on conflict(id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-speaking','speaking-1',1,'speaking','B1','Faire connaissance','Entretien dirigé · sans préparation','Présentez-vous. Parlez de votre parcours, de votre quotidien et d’un projet qui vous tient à cœur. Relances possibles : pourquoi ce projet ? Qu’aimeriez-vous apprendre ?','[]',null,null,120,0) on conflict(test_id,id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-speaking','speaking-2',2,'speaking','C1','Obtenir des renseignements','Je travaille dans un centre culturel de votre quartier. Vous souhaitez vous inscrire à une activité.','Posez-moi des questions pour choisir une activité : horaires, niveaux, tarifs, matériel et conditions d’inscription. Deux minutes de préparation, puis trois minutes trente d’interaction. Entraînement autonome : les réponses de l’interlocuteur sont proposées par thèmes.','[]',null,null,330,120) on conflict(test_id,id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('official-speaking','speaking-3',3,'speaking','C2','Progrès technique et liberté','Point de vue · sans préparation','Les technologies qui nous font gagner du temps nous rendent-elles nécessairement plus libres ? Développez votre position, examinez une objection et appuyez-vous sur des exemples précis.','[]',null,null,270,0) on conflict(test_id,id) do nothing;
insert into public.tests(id,skill,mode,title,duration_seconds,question_count,published) values('c2-listening','listening','c2','TCFme c2 listening',2100,39,true) on conflict(id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-23',1,'listening','C1','Un débat culturel','','Que propose l’intervenante ?','["Élargir les critères d’évaluation du succès","Limiter le nombre de visiteurs","Supprimer les statistiques","Rendre le musée payant"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-23',0,'La fréquentation brute ne décrit pas toute l’accessibilité culturelle.','listening-23.wav','Je me réjouis que le musée attire davantage de visiteurs. Mais le succès ne se résume pas aux entrées : il faut savoir qui revient, qui se sent accueilli et qui n’ose toujours pas franchir la porte.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-24',2,'listening','C1','Une sociologue','','Quelle critique formule-t-elle ?','["Les habitants sont indécis","Il y a trop d’options","Toute consultation est inutile","Une consultation sans pouvoir de cadrage peut être purement formelle"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-24',3,'La participation suppose un pouvoir sur la définition du problème.','listening-24.wav','Quand on demande aux habitants de participer après avoir fixé toutes les options, on recueille surtout leur assentiment. La participation commence vraiment lorsqu’ils peuvent redéfinir la question.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-25',3,'listening','C1','La gestion du risque','','Quel usage de l’argument est critiqué ?','["L’étude probabiliste","Son emploi pour éviter de justifier les choix","La publication des données","Le refus de promettre l’impossible"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-25',1,'L’impossibilité du risque nul ne légitime pas n’importe quel arbitrage.','listening-25.wav','Le risque zéro n’existe pas. Le dire ne dispense toutefois pas d’expliquer quels risques sont acceptés, par qui, et au bénéfice de qui. Sinon, une évidence technique devient une dispense de responsabilité.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-26',4,'listening','C1','Une chronique','','Quelle tension apparaît ?','["La liberté totale nuit aux résultats","Les objectifs sont absents","L’autonomie proclamée n’inclut pas la maîtrise des décisions","Les salariés refusent toute responsabilité"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-26',2,'La responsabilité est transférée sans pouvoir correspondant.','listening-26.wav','On félicite les salariés autonomes, à condition qu’ils atteignent des objectifs dont ils ne discutent ni la pertinence ni les moyens. Cette autonomie-là ressemble parfois à une responsabilité sans pouvoir.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-27',5,'listening','C1','L’économie circulaire','','Que suggère l’orateur ?','["Agir sur les incitations économiques","Cesser de réparer","Blâmer les consommateurs","Interdire tous les appareils"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-27',0,'Les conditions économiques doivent rendre la réparation praticable.','listening-27.wav','Réparer un appareil est une bonne chose. Mais si la réparation reste plus chère que le remplacement, invoquer la seule bonne volonté du consommateur laisse intact le système qui décourage le geste attendu.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-28',6,'listening','C1','L’histoire locale','','Quelle idée est contestée ?','["La nécessité du débat","L’existence du monument","La pluralité des lectures","L’existence d’un sens mémoriel unique et stable"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-28',3,'Le sens du monument s’est transformé historiquement.','listening-28.wav','Le monument paraît immuable. Pourtant, le sens qu’on lui attribue a changé plusieurs fois. Le débat actuel ne détruit donc pas une mémoire intacte ; il poursuit une histoire d’interprétations.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-29',7,'listening','C1','La traduction','','Quel paradoxe est exposé ?','["La traduction doit être littérale","Une transformation formelle peut préserver l’intention","Toute traduction est impossible","La courtoisie est universelle"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-29',1,'La fonction pragmatique peut exiger une formulation différente.','listening-29.wav','Traduire mot à mot peut préserver les unités et perdre le geste. Une formule courtoise dans une langue peut sembler distante dans une autre. La fidélité exige parfois de s’écarter de la forme.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-30',8,'listening','C1','Une décision publique','','Quelle exigence est posée ?','["Ne jamais agir dans l’urgence","Maintenir toutes les mesures","Réexaminer les décisions exceptionnelles","Supprimer toute règle"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-30',2,'Une justification temporaire impose une réévaluation ultérieure.','listening-30.wav','L’urgence justifie de décider vite. Elle ne justifie pas que les mesures provisoires se prolongent sans examen. Ce qui était défendable faute de temps doit pouvoir être rediscuté lorsque ce temps revient.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-31',9,'listening','C1','Un philosophe','','Quelle position défend-il ?','["Confronter les principes aux effets de leur application","Abandonner tous les principes","Ne juger que les intentions","Éviter toute action"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-31',0,'La portée normative des principes se vérifie aussi dans leurs effets.','listening-31.wav','À force d’opposer les principes aux conséquences, on oublie que nos principes ont précisément pour vocation d’orienter une action dans le monde. Les soustraire à toute confrontation avec leurs effets, c’est parfois les vider de leur exigence.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-32',10,'listening','C1','Une éditrice','','Quelle distinction est essentielle ?','["Longueur et brièveté","Fiction et essai","Original et traduction","Complexité du sujet et obscurité de l’expression"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-32',3,'L’obscurité stylistique ne prouve pas la profondeur.','listening-32.wav','Un texte difficile n’est pas nécessairement profond, pas plus qu’un texte clair n’est simpliste. La question est de savoir si la difficulté est celle de l’objet ou celle que l’écriture lui ajoute inutilement.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-33',11,'listening','C2','La reconnaissance','','Quelle limite est dénoncée ?','["Le manque de compliments","Une reconnaissance subordonnée à une identité figée","L’excès de transformations","La disparition des différences"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-33',1,'L’accueil conditionnel peut enfermer une personne dans une représentation.','listening-33.wav','Être reconnu à condition de correspondre à l’image que l’autre se fait de vous, est-ce encore être reconnu ? La reconnaissance devient fragile lorsqu’elle ne laisse aucune place à la transformation de celui qu’elle prétend accueillir.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-34',12,'listening','C2','Le débat scientifique','','Quelle distinction est demandée ?','["Science publique et science privée","Chercheurs anciens et débutants","Validité des connaissances et légitimité de leurs applications","Majorité et unanimité"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-34',2,'Une critique des usages ne contredit pas nécessairement les résultats.','listening-34.wav','Une controverse n’est pas résolue en additionnant les voix. Mais l’expertise ne gagne rien à traiter toute objection comme une ignorance. Il lui faut distinguer ce qui conteste les résultats de ce qui interroge les usages qu’on en fait.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-35',13,'listening','C2','La mémoire collective','','Quel effet possible est décrit ?','["Une mémoire institutionnalisée peut marginaliser d’autres souvenirs","Toute commémoration efface tout souvenir","La mémoire est impossible","Le récit commun reste toujours ouvert"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-35',0,'La sélection officielle peut réduire la pluralité des mémoires.','listening-35.wav','L’oubli n’est pas toujours le contraire de la mémoire. Une commémoration très codifiée peut fixer ce qu’il faut retenir et rendre moins audibles les souvenirs qui résistent à ce récit commun.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-36',14,'listening','C2','Une économiste','','Que risque de masquer cet éloge ?','["La fréquence des adaptations","Le courage individuel","L’existence des crises","Les causes structurelles des crises"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-36',3,'L’attention portée à l’adaptation peut détourner de la prévention structurelle.','listening-36.wav','On présente la résilience comme la capacité de s’adapter aux crises. Mais si l’on célèbre uniquement l’adaptation de ceux qui les subissent, on risque de ne plus interroger les décisions qui les rendent récurrentes.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-37',15,'listening','C2','L’ironie d’un chroniqueur','','Quelle intention domine ?','["Féliciter la modernisation","Dénoncer ironiquement une complication","Expliquer une procédure neutre","Demander une nouvelle application"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-37',1,'Le compliment initial est contredit par l’accumulation des obstacles.','listening-37.wav','Quelle merveilleuse simplification : il faut désormais trois applications, deux comptes et un code reçu par courrier pour demander le document que le guichet délivrait en cinq minutes.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-38',16,'listening','C2','La transmission','','Quelle conception est défendue ?','["La reproduction fidèle de chaque usage","Le rejet de tout héritage","Une appropriation qui transforme l’héritage","La conservation sans interprétation"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-38',2,'La transmission vivante implique une réinterprétation.','listening-38.wav','Transmettre n’est pas remettre un objet intact à quelqu’un qui le garderait intact à son tour. C’est accepter qu’il change de sens dans des mains nouvelles, sans quoi on ne transmettrait qu’une obligation de répétition.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-39',17,'listening','C2','Le langage de la nécessité','','Quelle inférence est récusée ?','["D’un problème incontournable découlerait une solution unique","Un problème peut être discuté","Une réforme peut avoir des raisons","Plusieurs solutions peuvent exister"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-39',0,'L’existence d’une contrainte ne détermine pas à elle seule une réponse.','listening-39.wav','Dire qu’une réforme est nécessaire peut ouvrir une discussion sur ses raisons. Dire qu’elle est la seule possible tend au contraire à soustraire ses modalités au débat. La nécessité du problème ne rend pas unique sa solution.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-1',18,'listening','A1','Annonce de gare','','Sur quelle voie faut-il aller ?','["Voie deux","Voie quatre","Voie six","Voie dix"]',null,null,null,null) on conflict(test_id,id) do nothing;
