insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-2',19,'listening','A1','Au café','','Que commande la première personne ?','["Un thé nature","Un café sucré","Un café sans sucre","Un jus de citron"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-2',2,'Elle demande explicitement un café sans sucre.','listening-2.wav','Pour moi, un café sans sucre, s’il vous plaît. Mon amie prendra un thé au citron.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-3',20,'listening','A1','Message téléphonique','','À quelle heure faut-il retrouver Paul ?','["À vingt heures","À dix-neuf heures","À dix-huit heures","À vingt et une heures"]',null,null,null,null) on conflict(test_id,id) do nothing;
