insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-5',22,'listening','A2','Au centre sportif','','Qu’est-ce qui change ?','["Le prix","Le lieu","Le professeur","L’heure"]',null,null,null,null) on conflict(test_id,id) do nothing;
