insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-9',26,'listening','B1','Un service municipal','','Que propose la mairie le mercredi ?','["Des billets gratuits","Une aide à l’inscription","Une permanence médicale","Un accès sans inscription"]',null,null,null,null) on conflict(test_id,id) do nothing;
