insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-11',28,'listening','B1','Un abonnement','','Quel conseil donne la personne ?','["Choisir une formule flexible en cas d’incertitude","Payer une année immédiatement","Annuler tout abonnement","Acheter deux formules"]',null,null,null,null) on conflict(test_id,id) do nothing;
