insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-12',3,'Le besoin concerne le temps de tri.','listening-12.wav','Nous ne manquons pas d’objets à distribuer, mais de personnes pour les trier. Deux heures le samedi nous aideraient davantage qu’un nouveau don de vêtements.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-13',30,'listening','B1','Une visite guidée','','Quelle conséquence ont les travaux ?','["La visite est annulée","La visite sera plus longue","Le billet sera plus cher","Le jardin sera fermé"]',null,null,null,null) on conflict(test_id,id) do nothing;
