insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-14',31,'listening','B2','Un entretien radio','','Que remet en cause l’intervenante ?','["La valeur des bibliothèques","Le prix des livres","La pertinence d’un indicateur unique","La lecture sur téléphone"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-14',2,'Les achats ne couvrent pas toutes les pratiques de lecture.','listening-14.wav','On dit que les jeunes ne lisent plus. Pourtant, on mesure souvent seulement les livres achetés. Les lectures sur téléphone, les emprunts et les textes partagés échappent à ce chiffre.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-15',32,'listening','B2','Au travail','','Quel bilan est proposé ?','["Le gain local ne garantit pas un gain global","Le logiciel ne fonctionne jamais","La saisie est devenue plus lente","Les dossiers doivent être supprimés"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-15',0,'Le temps économisé peut être absorbé par d’autres tâches.','listening-15.wav','Le nouveau logiciel nous fait gagner du temps pour saisir les dossiers. Mais nous passons maintenant ce temps à corriger les classements automatiques. Il faudrait mesurer l’ensemble du processus.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-16',33,'listening','B2','Un quartier en débat','','Quelle est la position du commerçant ?','["Il refuse les vélos","Il demande un stationnement permanent","Il veut fermer la rue","Il souhaite aménager le projet"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-16',3,'Il soutient le principe sous réserve d’une organisation des livraisons.','listening-16.wav','Je suis favorable aux pistes cyclables. Ce que je demande, c’est de maintenir un accès pour les livraisons tôt le matin. On peut concilier les deux si l’on discute des horaires.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-17',34,'listening','B2','Une chercheuse','','Quelle prudence exprime-t-elle ?','["Les résultats sont inutiles","Une corrélation ne suffit pas à établir une causalité exclusive","Le sommeil ne compte jamais","Les conditions de vie sont identiques"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-17',1,'D’autres facteurs peuvent contribuer à l’association observée.','listening-17.wav','Nous avons observé une relation entre sommeil et réussite. Cela ne prouve pas, à lui seul, que dormir davantage explique tous les résultats : les conditions de vie interviennent aussi.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-18',35,'listening','B2','Une émission québécoise','','Quel enjeu est souligné ?','["Le remplacement des téléphones","Le prix du permis","La couverture territoriale du service","La suppression des réservations"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-18',2,'Une bonne application ne compense pas le manque de véhicules proches.','listening-18.wav','L’autopartage fonctionne bien au centre-ville. Mais dans les secteurs où les véhicules sont rares, réserver devient une petite expédition. Étendre le réseau compte autant que proposer une application pratique.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-19',36,'listening','B2','L’enseignement','','Pourquoi l’enseignant diffère-t-il la réponse ?','["Pour favoriser la réflexion","Pour gagner du temps","Pour sanctionner l’élève","Pour éviter le sujet"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-19',0,'L’explication du raisonnement est un outil d’apprentissage.','listening-19.wav','Donner la bonne réponse immédiatement rassure l’élève, mais peut lui retirer l’occasion de comprendre son erreur. Je préfère parfois lui demander d’expliquer son raisonnement.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-20',37,'listening','B2','Un restaurateur','','Quel compromis est présenté ?','["Des prix plus élevés contre un meilleur décor","Une cuisine plus rapide mais moins fraîche","Plus de choix avec plus de déchets","Moins de choix permanent avec davantage de fraîcheur"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-20',3,'La réduction de la carte permet de suivre les arrivages.','listening-20.wav','Notre carte est plus courte depuis un mois. Certains clients s’en étonnent, puis apprécient que les plats changent avec les arrivages. Nous gaspillons moins et cuisinons plus frais.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-21',38,'listening','B2','Une médiatrice','','Quel est l’objectif ?','["Obtenir une opinion unique","Maintenir un dialogue malgré le désaccord","Éviter tous les sujets sensibles","Désigner un gagnant"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-21',1,'La médiation vise les conditions du dialogue.','listening-21.wav','Nous ne cherchons pas à faire disparaître les divergences. Nous voulons que chacun puisse les exprimer sans que la discussion s’interrompe au premier désaccord.') on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-listening','listening-22',39,'listening','B2','La rénovation','','Quel risque est évoqué ?','["Une baisse de température","Une hausse de la consommation","L’éviction des bénéficiaires visés","Une disparition des bâtiments"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-listening','listening-22',2,'Le bénéfice écologique peut s’accompagner d’un déplacement social.','listening-22.wav','Isoler les bâtiments est indispensable. Encore faut-il vérifier que l’augmentation des loyers ne chasse pas les habitants auxquels les économies d’énergie étaient censées profiter.') on conflict(test_id,question_id) do nothing;
insert into public.tests(id,skill,mode,title,duration_seconds,question_count,published) values('c2-reading','reading','c2','TCFme c2 reading',3600,39,true) on conflict(id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-23',1,'reading','C1','La mesure du mérite','Un concours identique pour tous ne neutralise pas les inégalités de préparation. Confondre l’uniformité de la procédure avec l’équité des conditions revient à attribuer aux seuls individus des écarts dont une partie les précède.','Quelle présupposition est contestée ?','["La nécessité de critères","L’existence d’efforts personnels","La possibilité d’un concours","L’égalité des règles suffirait à assurer l’équité"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-23',3,'Des règles identiques ne compensent pas des conditions initiales inégales.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-24',2,'reading','C1','L’expertise en débat','Reconnaître les limites d’un modèle n’invalide pas l’expertise ; c’est au contraire rendre explicite le domaine où elle éclaire la décision. L’assurance sans réserve, elle, confond autorité scientifique et posture d’infaillibilité.','Quelle conception de l’expertise est privilégiée ?','["Une compétence qui explicite son incertitude","Une certitude définitive","Une opinion équivalente à toute autre","Une autorité soustraite au débat"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-24',0,'L’incertitude circonscrite contribue à la rigueur de l’expertise.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-25',3,'reading','C1','La sobriété choisie','L’injonction à consommer moins paraît consensuelle tant qu’elle reste abstraite. Elle change de sens selon qu’elle vise un confort superflu ou un besoin déjà contraint. Sans cette distinction, la sobriété risque de devenir le langage vertueux d’une privation imposée.','Quel préalable l’auteur exige-t-il ?','["Supprimer toute consommation","Reconnaître l’inégale marge de choix","Appliquer un quota identique","Renoncer aux objectifs écologiques"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-25',1,'Le texte distingue renoncement volontaire et privation subie.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-26',4,'reading','C1','Des données ouvertes','Ouvrir une base ne la rend pas intelligible. Sans documentation des catégories, des absences et des changements de méthode, la transparence formelle peut nourrir des conclusions plus trompeuses que le silence.','Quelle condition rend l’ouverture utile ?','["La multiplication des chiffres","L’anonymat des producteurs","L’explication des choix de construction","La suppression des données manquantes"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-26',2,'Les métadonnées permettent d’interpréter correctement les chiffres.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-27',5,'reading','C1','L’hospitalité urbaine','Une place peut être accessible en droit et dissuasive dans ses aménagements. Les assises empêchant de s’allonger matérialisent une sélection des usages sans qu’aucune interdiction n’ait à être formulée.','Que révèle l’aménagement décrit ?','["Une augmentation du confort","Une absence de choix politique","Une simple contrainte esthétique","Une exclusion opérée par la conception matérielle"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-27',3,'Le mobilier impose implicitement une règle d’usage.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-28',6,'reading','C1','Le droit à l’erreur','Une institution qui célèbre l’expérimentation tout en sanctionnant chaque échec produit moins de prudence que de dissimulation. On ne peut demander aux agents de prendre des risques et leur retirer simultanément la possibilité d’en rendre compte.','Quel mécanisme est dénoncé ?','["Une injonction contradictoire favorisant la dissimulation","Un excès de transparence","Une absence totale de sanctions","La généralisation de l’imprudence"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-28',0,'L’écart entre discours et sanctions encourage à cacher les échecs.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-29',7,'reading','C1','L’attention comme ressource','L’abondance des contenus ne se traduit pas mécaniquement par un élargissement des horizons. Lorsque leur sélection récompense surtout ce qui retient déjà notre attention, la diversité disponible peut croître tandis que la diversité effectivement rencontrée se rétrécit.','Quelle distinction fonde le raisonnement ?','["Création et propriété","Offre potentielle et exposition réelle","Information et divertissement","Gratuité et abonnement"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-29',1,'La diversité du catalogue ne garantit pas celle des contenus proposés.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-30',8,'reading','C1','Un futur négociable','Présenter une technologie comme inéluctable dispense de discuter les institutions qui la façonnent. Ce récit ne décrit pas seulement un avenir : il réduit le champ des futurs qu’il devient légitime d’envisager.','Quelle fonction le récit remplit-il ?','["Il prouve une nécessité technique","Il ouvre toutes les options","Il restreint politiquement les alternatives","Il décrit uniquement le passé"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-30',2,'L’inéluctabilité proclamée ferme le débat sur les choix collectifs.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-31',9,'reading','C1','Une neutralité située','Le protocole ne contient aucun critère explicitement discriminatoire. Encore faut-il examiner les variables qu’il prend pour acquises : un indicateur apparemment neutre peut hériter des inégalités du monde dont il est extrait.','Que signifie « hériter » ici ?','["Corriger automatiquement","Être transmis juridiquement","Mesurer sans sélection","Reproduire indirectement des inégalités antérieures"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-31',3,'La neutralité formelle peut conserver des biais présents dans les données.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-32',10,'reading','C1','Le compromis','Le compromis n’est fécond ni parce qu’il partagerait chaque désaccord en deux, ni parce qu’il ferait disparaître le conflit. Il l’est lorsqu’il transforme les conditions dans lesquelles les parties peuvent continuer à agir ensemble sans feindre de penser de même.','Quelle définition est proposée ?','["Un accord pratique compatible avec un désaccord persistant","Une moyenne arithmétique des opinions","Une conversion réciproque complète","Une suspension de toute action"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-32',0,'La coopération n’exige pas l’identité des convictions.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-33',11,'reading','C2','L’archive et l’oubli','Ce que conserve une archive témoigne aussi des procédures qui ont décidé de sa conservation. Prendre son silence pour la preuve d’une absence revient à effacer une seconde fois ceux dont la parole n’avait pas vocation à y entrer.','Quelle erreur méthodologique est visée ?','["Dater les documents","Confondre absence de trace et inexistence historique","Comparer plusieurs archives","Décrire les procédures de collecte"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-33',1,'Le corpus reflète une sélection préalable, non la totalité du passé.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-34',12,'reading','C2','L’éloge du provisoire','On reproche au provisoire de ne pas tenir ses promesses de permanence. Mais c’est lui prêter un projet qui n’est pas le sien. Une décision révisable peut être plus responsable qu’un engagement dont la solennité interdit ensuite de reconnaître les effets indésirables.','Quel renversement l’auteur opère-t-il ?','["L’irréversibilité devient un idéal","Toute promesse devient inutile","La révisabilité devient une exigence de responsabilité","L’inaction devient une décision"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-34',2,'La capacité de corriger est valorisée comme une responsabilité.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-35',13,'reading','C2','La communauté imaginée','On invoque volontiers une communauté pour légitimer une décision prise en son nom. Reste à savoir si ce « nous » désigne ceux qui ont participé à la délibération ou ceux à qui l’on demande seulement d’en assumer les conséquences.','Quelle ambiguïté est examinée ?','["Le sens géographique de communauté","L’opposition entre passé et avenir","Le nombre exact des participants","L’écart entre auteurs et destinataires d’une décision collective"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-35',3,'Le pronom collectif peut masquer une dissymétrie de pouvoir.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-36',14,'reading','C2','La lenteur administrative','Que la lenteur protège parfois de l’arbitraire ne suffit pas à en faire une vertu en soi. Tout dépend de ce qu’elle suspend : la précipitation d’un pouvoir ou l’exercice d’un droit. Un même délai peut être garantie pour l’un et déni pour l’autre.','À quoi tient l’ambivalence du délai ?','["À l’objet suspendu et à la position des personnes","À sa seule durée","À l’intention toujours malveillante des agents","À l’inutilité des procédures"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-36',0,'Le jugement dépend de la fonction du délai et de ses effets différenciés.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-37',15,'reading','C2','Le récit de la réussite','Le récit rétrospectif donne aux bifurcations heureuses l’allure d’une trajectoire maîtrisée. Ce n’est pas qu’il invente tous les faits ; il redistribue leur nécessité, reléguant la contingence au rang de décor.','Quelle opération narrative est décrite ?','["La fabrication intégrale des événements","La transformation du hasard en cohérence apparente","Le refus de toute causalité","La disparition des protagonistes"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-37',1,'Le récit construit après coup une nécessité qui n’existait pas dans l’action.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-38',16,'reading','C2','La promesse d’inclusion','Inclure peut signifier inviter chacun à rejoindre un cadre inchangé, ou reconnaître à ceux qui arrivent le pouvoir d’en modifier les règles. Entre ces deux gestes se joue moins une différence de générosité qu’une redistribution de l’autorité.','Quel critère distingue les deux conceptions ?','["Le nombre de bénéficiaires","Le coût de l’accueil","La capacité des nouveaux venus à transformer le cadre","La rapidité des invitations"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-38',2,'La seconde conception partage le pouvoir de définir les règles.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-39',17,'reading','C2','L’exigence de preuve','Il est légitime d’exiger des preuves d’un dommage ; il l’est moins de fixer un seuil que seule la survenue irréversible du dommage permettrait d’atteindre. La rigueur apparente peut alors devenir une manière de rendre la prévention conceptuellement impossible.','Quel paradoxe est dénoncé ?','["La prévention dispense de toute preuve","Le dommage est toujours mesurable","La preuve interdit toute décision","Un standard probatoire peut n’être satisfait qu’une fois la prévention devenue impossible"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-39',3,'Le seuil exigé peut contredire la finalité préventive de la décision.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-1',18,'reading','A1','À la bibliothèque','La bibliothèque ferme à 18 h du lundi au vendredi. Le samedi, elle ouvre de 9 h à 13 h.','Quand peut-on venir le samedi ?','["À 10 h","À 15 h","À 18 h","À 20 h"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-1',0,'Le créneau du samedi est de 9 h à 13 h.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-2',19,'reading','A1','Un rendez-vous','Bonjour Léa, notre rendez-vous de mardi est déplacé à jeudi, à la même heure : 14 h. À bientôt !','Quand a lieu le rendez-vous ?','["Mardi à 14 h","Jeudi à 14 h","Jeudi à 16 h","Mardi à 16 h"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-2',1,'Seul le jour change.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-3',20,'reading','A1','Petite annonce','À louer : studio meublé, proche du métro. Loyer : 720 euros, eau comprise. Électricité en supplément.','Quelle dépense est incluse ?','["L’électricité","Internet","L’eau","Le transport"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-3',2,'« Eau comprise » signifie qu’elle est incluse dans le loyer.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-4',21,'reading','A1','Au musée','Les visiteurs de moins de 18 ans entrent gratuitement. Pour les autres, le billet coûte 8 euros.','Qui ne paie pas ?','["Tous les visiteurs","Les plus de 65 ans","Les étudiants de 25 ans","Les enfants de 12 ans"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-4',3,'Les enfants de 12 ans ont moins de 18 ans.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-5',22,'reading','A2','Une livraison','Votre colis sera livré vendredi entre 8 h et 12 h. En cas d’absence, il sera déposé au point relais situé face à la mairie.','Où retirer le colis si vous êtes absent ?','["À la mairie","Dans un point relais","Chez un voisin","À la poste centrale"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-5',1,'Le dépôt annoncé est au point relais, en face de la mairie.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-6',23,'reading','A2','Un atelier','L’atelier de réparation est ouvert à tous. Apportez votre objet et ses pièces de rechange. Les bénévoles vous aident, mais ne réparent pas à votre place.','Que doit faire le participant ?','["Acheter un objet neuf","Déposer son objet et partir","Participer à la réparation","Payer les bénévoles"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-6',2,'L’aide accompagne une réparation faite par le participant.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-7',24,'reading','A2','La piscine','À partir de lundi, le bassin sera réservé aux écoles chaque matin. Les particuliers pourront nager à partir de midi, sauf le mercredi où l’ouverture reste fixée à 9 h.','Quand un particulier peut-il nager mercredi ?','["Dès 9 h","Seulement après midi","Uniquement le soir","À aucun moment"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-7',0,'Le mercredi constitue une exception explicite.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-8',25,'reading','A2','Une inscription','Les dossiers reçus avant le 15 mai seront examinés en priorité. Les dossiers tardifs pourront être étudiés si des places restent disponibles.','Que signifie un envoi après le 15 mai ?','["L’admission est garantie","Le tarif double","Le dossier est détruit","L’examen du dossier reste possible"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-8',3,'Un dépôt tardif est conditionné aux places restantes.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-9',26,'reading','B1','Un voyage partagé','Le covoiturage du village fonctionne sur réservation. Une place réservée mais non annulée la veille sera facturée, même en cas d’absence.','Dans quel cas paie-t-on sans voyager ?','["Si le conducteur annule","Si l’on oublie d’annuler à temps","Si l’on réserve la veille","Si le trajet est complet"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-9',1,'L’absence sans annulation dans les délais entraîne une facturation.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-10',27,'reading','B1','Travailler autrement','L’entreprise propose deux jours de télétravail, sous réserve que chaque équipe maintienne une présence quotidienne au bureau. Les salariés doivent donc coordonner leurs choix.','Quelle condition limite la liberté de choix ?','["L’ancienneté des salariés","La distance du domicile","La présence quotidienne d’une partie de l’équipe","L’achat d’un ordinateur"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-10',2,'L’organisation collective prime sur le choix individuel des jours.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-11',28,'reading','B1','Une place publique','Après trois mois d’essai, la mairie maintient la piétonnisation du dimanche. Les commerçants observent moins de passages rapides, mais davantage de clients qui restent dans le quartier.','Quel bilan les commerçants font-ils ?','["Tous leurs clients ont disparu","Les habitudes de fréquentation ont changé","Les ventes ont nécessairement doublé","La rue reste ouverte aux voitures"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-11',1,'Le texte oppose rapidité du passage et durée de présence, sans chiffrer les ventes.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-12',29,'reading','B1','Une formation','Le cours est gratuit pour les demandeurs d’emploi. Toutefois, une caution est demandée puis remboursée à ceux qui assistent à au moins huit séances sur dix.','À quoi sert la caution ?','["À encourager l’assiduité","À financer les diplômes","À sélectionner les meilleurs","À payer chaque séance"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-12',0,'Le remboursement dépend de la présence, non des résultats.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-13',30,'reading','B1','Une collecte','La collecte locale accepte les vêtements propres, même démodés. En revanche, les articles humides sont refusés : ils risquent d’abîmer tout le lot.','Pourquoi certains articles sont-ils refusés ?','["Parce qu’ils sont anciens","Parce qu’ils sont bon marché","Pour protéger les autres vêtements","Parce qu’ils sont trop nombreux"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-13',2,'L’humidité peut détériorer l’ensemble de la collecte.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-14',31,'reading','B2','Le temps des réunions','Supprimer une réunion ne supprime pas nécessairement le travail qu’elle organisait. Faute de règles claires, les échanges se dispersent dans des messages plus nombreux, et le gain de temps annoncé s’évanouit.','Quelle idée l’auteur défend-il ?','["Toute réunion est indispensable","Les messages doivent être interdits","Les réunions augmentent toujours la productivité","Réduire les réunions exige de repenser la coordination"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-14',3,'La critique porte sur l’absence de solution organisationnelle.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-15',32,'reading','B2','Manger local','La proximité géographique est un indicateur utile, mais incomplet. Un produit cultivé sous serre chauffée à quelques kilomètres peut consommer plus d’énergie qu’un produit de saison transporté de plus loin.','Quelle conclusion peut-on tirer ?','["Local signifie toujours écologique","Il faut considérer le mode de production","Le transport est sans effet","Les serres sont toutes interdites"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-15',1,'Le bilan dépend aussi des conditions de production.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-16',33,'reading','B2','Les transports gratuits','La gratuité attire des usagers, mais une ligne rare et saturée reste peu séduisante pour ceux qui disposent d’une voiture. Le prix n’est qu’un élément du choix de mobilité.','Quelle mesure complémentaire est suggérée ?','["Améliorer la fréquence et la capacité","Augmenter le stationnement","Interdire les vélos","Supprimer les lignes rurales"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-16',0,'Le texte souligne deux obstacles de qualité de service.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-17',34,'reading','B2','Lire les statistiques','Le salaire moyen a progressé, alors que la moitié des employés n’a reçu aucune augmentation. Quelques fortes hausses au sommet suffisent à modifier la moyenne sans améliorer la situation de la majorité.','Que révèle cet exemple ?','["La moyenne est nécessairement fausse","Tous les salaires ont diminué","Un indicateur global peut masquer des écarts","Les hausses individuelles sont impossibles"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-17',2,'La moyenne agrège les valeurs sans décrire leur répartition.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-18',35,'reading','B2','Une ville fraîche','Planter des arbres est nécessaire, mais les compter ne suffit pas. Une jeune plantation n’offre ni l’ombre ni la résistance d’un arbre ancien. Préserver l’existant doit donc accompagner les annonces de nouvelles plantations.','Que critique l’auteur ?','["L’usage des espaces publics","L’attention exclusive au nombre d’arbres plantés","Toute plantation nouvelle","Le coût des jardins privés"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-18',1,'Le nombre ne rend pas compte du service écologique effectif.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-19',36,'reading','B2','L’apprentissage numérique','La plateforme promet un parcours personnalisé. Pourtant, ses recommandations se fondent surtout sur les réponses passées. Un élève momentanément en difficulté peut alors recevoir des exercices toujours plus faciles et ne plus rencontrer de nouveaux défis.','Quel risque est décrit ?','["L’absence de données","Un apprentissage trop rapide","Une suppression des exercices","L’enfermement dans un profil initial"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-19',3,'Les recommandations peuvent figer la difficulté au lieu de soutenir la progression.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-20',37,'reading','B2','La semaine courte','Passer à quatre jours sans réduire la charge peut accroître l’intensité du travail. Le bénéfice dépend donc moins du calendrier que de la capacité à supprimer les tâches inutiles et à fixer des priorités.','Quelle distinction organise l’argument ?','["Durée affichée et organisation réelle","Salaire public et salaire privé","Travail manuel et travail intellectuel","Repos individuel et repos collectif"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-20',0,'Un calendrier réduit ne garantit pas une charge réduite.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-21',38,'reading','B2','Le patrimoine vivant','Restaurer un marché en conservant ses façades, mais en remplaçant ses commerces par des boutiques de luxe, sauve une image et transforme un usage. La préservation matérielle peut ainsi coïncider avec une rupture sociale.','Quel paradoxe est mis en évidence ?','["La restauration détruit toutes les façades","Les commerces ne changent jamais","On peut préserver le bâti tout en perdant une fonction collective","Le luxe protège nécessairement les habitants"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-21',2,'L’opposition porte sur le patrimoine architectural et la vie sociale.',null,null) on conflict(test_id,question_id) do nothing;
insert into public.questions(test_id,id,position,skill,level,title,passage,prompt,options,min_words,max_words,duration_seconds,preparation_seconds) values('c2-reading','reading-22',39,'reading','B2','L’information en continu','La rapidité devient un avantage commercial lorsqu’elle précède la vérification. Mais ce qui attire l’attention à court terme peut détériorer durablement la confiance dont dépend le média.','Quel conflit l’auteur identifie-t-il ?','["Neutralité et absence de lecteurs","Rentabilité immédiate et crédibilité durable","Presse écrite et radio","Vitesse de lecture et taille des écrans"]',null,null,null,null) on conflict(test_id,id) do nothing;
insert into private.answer_keys(test_id,question_id,correct,rationale,audio_path,script) values('c2-reading','reading-22',1,'L’intérêt commercial immédiat peut miner la confiance future.',null,null) on conflict(test_id,question_id) do nothing;
